using System;
using System.IO;
using System.Linq;
using System.Diagnostics;
using System.Threading;

class StopTests {
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);Console.WriteLine("PASS "+message);}
 static int Main(string[] args){
  if(args.Length>0&&args[0]=="--leaf"){Thread.Sleep(60000);return 0;}
  if(args.Length>0&&args[0]=="--tree"){string treeRun=JobOwnership.Context;while(!File.Exists(Path.Combine(treeRun,"start.ready")))Thread.Sleep(10);using(var p=Process.Start(new ProcessStartInfo(Process.GetCurrentProcess().MainModule.FileName,"--leaf"){UseShellExecute=false,CreateNoWindow=true})){File.WriteAllText(Path.Combine(treeRun,"leaf.pid"),p.Id.ToString());Thread.Sleep(60000);}return 0;}
  string root=Path.Combine(AppStorage.DataRoot,"StopTests_"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);string project=Path.Combine(root,"project");Directory.CreateDirectory(project);string original=Path.Combine(project,"part.sldprt");File.WriteAllText(original,"original");string previous=Path.Combine(project,"project_1");Directory.CreateDirectory(previous);File.WriteAllText(Path.Combine(previous,"successful.dxf"),"previous");string meta=Path.Combine(previous,"PACKAGE.json");File.WriteAllText(meta,"previous metadata");
  string ctx=Path.Combine(root,"job");Directory.CreateDirectory(ctx);Environment.SetEnvironmentVariable("SOLIDWORKSBREP_RUN_CONTEXT",ctx);JobOwnership.BackupFile(meta,project);JobOwnership.OwnDirectory(Path.Combine(previous,"Profile"),project);File.WriteAllText(Path.Combine(previous,"Profile","partial.pdf"),"partial");File.WriteAllText(meta,"reserved");JobOwnership.Cleanup(ctx);Check(File.ReadAllText(meta)=="previous metadata"&&File.Exists(Path.Combine(previous,"successful.dxf")),"shared previous result and metadata preserved");Check(!Directory.Exists(Path.Combine(previous,"Profile"))&&File.ReadAllText(original)=="original","current role deleted, source preserved");
  bool rejected=false;try{JobOwnership.OwnDirectory(root,project);}catch{rejected=true;}Check(rejected,"outside-project target refused");rejected=false;try{JobOwnership.OwnDirectory(previous,project);}catch{rejected=true;}Check(rejected,"nonempty historical result refused");
  string newCtx=Path.Combine(root,"new-job");Directory.CreateDirectory(newCtx);Environment.SetEnvironmentVariable("SOLIDWORKSBREP_RUN_CONTEXT",newCtx);string output=Path.Combine(project,"project_2");JobOwnership.OwnDirectory(output,project);File.WriteAllText(Path.Combine(output,"part.dxf"),"partial");JobOwnership.Cleanup(newCtx);JobOwnership.Cleanup(newCtx);Check(!Directory.Exists(output),"new result deleted and repeat cleanup is harmless");
  string refused=Path.Combine(root,"refused-job");Directory.CreateDirectory(refused);Environment.SetEnvironmentVariable("SOLIDWORKSBREP_RUN_CONTEXT",refused);JobOwnership.OwnDirectory(output,project);File.Delete(Path.Combine(output,".swbrep-run-owner"));rejected=false;try{JobOwnership.Cleanup(refused);}catch{rejected=true;}Check(rejected&&Directory.Exists(output),"missing ownership marker prevents deletion");
  string merge=Path.Combine(root,"merge-job");Directory.CreateDirectory(merge);Environment.SetEnvironmentVariable("SOLIDWORKSBREP_RUN_CONTEXT",merge);string package=Path.Combine(previous,"MERGE.json");File.WriteAllText(package,"{\"roles\":{\"DXF\":\"READY\"}}");JobOwnership.BackupPackage(package,project,"Profile");File.WriteAllText(package,"{\"roles\":{\"DXF\":\"READY\",\"Profile\":\"RESERVED\",\"Faces\":\"READY\"}}");JobOwnership.Cleanup(merge);Check(File.ReadAllText(package).Contains("Faces")&&!File.ReadAllText(package).Contains("Profile"),"other completed role survives shared metadata rollback");File.WriteAllText(package,"later result");JobOwnership.Cleanup(merge);Check(File.ReadAllText(package)=="later result","repeat rollback never overwrites later metadata");
  string locked=Path.Combine(root,"locked-job");Directory.CreateDirectory(locked);Environment.SetEnvironmentVariable("SOLIDWORKSBREP_RUN_CONTEXT",locked);string lockedOutput=Path.Combine(project,"project_4");JobOwnership.OwnDirectory(lockedOutput,project);string lockFile=Path.Combine(project,new DirectoryInfo(project).Name+"_temp","layout.lock");using(var guard=new FileStream(lockFile,FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){rejected=false;try{JobOwnership.Cleanup(locked);}catch(IOException){rejected=true;}Check(rejected&&Directory.Exists(lockedOutput),"busy layout postpones deletion");}JobOwnership.Cleanup(locked);Check(!Directory.Exists(lockedOutput),"cleanup retry succeeds after lock release");
  Environment.SetEnvironmentVariable("SOLIDWORKSBREP_RUN_CONTEXT",null);string integration=Path.Combine(root,"integration");Directory.CreateDirectory(integration);string integrationSource=Path.Combine(integration,"part.sldprt");File.WriteAllText(integrationSource,"model");string prior=SharedResultFolder.Reserve(integration,integrationSource,"HASH","Default","DXF");SharedResultFolder.Complete(prior,"DXF",true);File.WriteAllText(Path.Combine(prior,"DXF","good.dxf"),"good");string integrationRun=Path.Combine(root,"integration-run");Directory.CreateDirectory(integrationRun);Environment.SetEnvironmentVariable("SOLIDWORKSBREP_RUN_CONTEXT",integrationRun);string reused=SharedResultFolder.Reserve(integration,integrationSource,"HASH","Default","Profile");Check(reused==prior,"real allocator reuses successful package without claiming historical DXF");File.WriteAllText(Path.Combine(reused,"Profile","bad.pdf"),"partial");File.WriteAllText(Path.Combine(reused,"PROFILES_RESULT.json"),"partial report");File.WriteAllText(Path.Combine(reused,"READ_ME_Profile_en.txt"),"partial note");JobOwnership.Cleanup(integrationRun);Check(File.Exists(Path.Combine(prior,"DXF","good.dxf"))&&!Directory.Exists(Path.Combine(prior,"Profile"))&&!File.Exists(Path.Combine(prior,"PROFILES_RESULT.json"))&&!File.Exists(Path.Combine(prior,"READ_ME_Profile_en.txt")),"real shared package cleanup removes report and delivery note only from cancelled module");
  Environment.SetEnvironmentVariable("SOLIDWORKSBREP_RUN_CONTEXT",null);var info=new ProcessStartInfo(Process.GetCurrentProcess().MainModule.FileName,"--tree"){UseShellExecute=false,CreateNoWindow=true};JobControl.Prepare(info);string run=JobOwnership.Context;JobOwnership.OwnDirectory(Path.Combine(project,"project_3"),project);using(var p=Process.Start(info)){JobControl.Started(p);var watch=Stopwatch.StartNew();string pidFile=Path.Combine(run,"leaf.pid");while(!File.Exists(pidFile)){if(watch.Elapsed.TotalSeconds>10)throw new Exception("child spawn timeout");Thread.Sleep(20);}int leaf=int.Parse(File.ReadAllText(pidFile));string result=JobControl.ForceStop().GetAwaiter().GetResult();Check(result=="STOP_CLEANED","force stop confirms process exit before cleanup");Check(p.HasExited&&!Directory.Exists(Path.Combine(project,"project_3")),"owned worker stopped and outputs deleted");bool alive=false;try{using(var child=Process.GetProcessById(leaf))alive=!child.HasExited;}catch(ArgumentException){}Check(!alive,"grandchild process stopped");Check(File.ReadAllText(original)=="original"&&File.Exists(Path.Combine(previous,"successful.dxf")),"source and previous results survive forced stop");}
  Console.WriteLine("Stop/cleanup acceptance PASS; no SolidWorks called or terminated.");return 0;
 }
}
